<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;

class Profile extends Model
{
    // is_active, is_verified and verified_at are NOT fillable: only our services change them.
    // active_user_id is generated by the database and must never be written.
    protected $fillable = [
        'display_name',
        'job_title_id',
        'city_id',
        'profile_image',
        'cover_image',
        'bio',
        'study',
        'experience',
    ];

    protected function casts(): array
    {
        return [
            'is_active' => 'boolean',
            'is_verified' => 'boolean',
            'verified_at' => 'datetime',
        ];
    }

    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    public function jobTitle(): BelongsTo
    {
        return $this->belongsTo(JobTitle::class);
    }

    public function city(): BelongsTo
    {
        return $this->belongsTo(City::class);
    }

    // Phase 2, feature 6: contact links (one per platform).
    public function socialLinks(): HasMany
    {
        return $this->hasMany(SocialLink::class);
    }

    // Phase 2, feature 7: the work gallery.
    public function galleryImages(): HasMany
    {
        return $this->hasMany(GalleryImage::class);
    }

    // Phase 2, feature 8: the place of work (one or none).
    public function location(): HasOne
    {
        return $this->hasOne(ProfileLocation::class);
    }
}
